-- Actual current schema, including all B14 guards. Local fixtures only.
create table public.b18_scope(kind text primary key,lid uuid,offer uuid,oid uuid,batch uuid,cmd uuid);
grant select on public.b18_scope to authenticated;
insert into public.b18_scope(kind,lid) values('cost',public.b14_draft(81)),('suspended',public.b14_draft(85));
select set_config('request.jwt.claim.sub',public.b14_owner(81)::text,false);
set role authenticated;
select public.b14_assert((public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'))->>'revision')::bigint=0,'missing cost is unknown');
select public.b14_assert(public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'))->'amountCents'='null'::jsonb,'unknown not zero');
select public.b14_assert((public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":0,"currency":"CAD","revision":0}')->>'revision')::bigint=1,'explicit zero');
select public.b14_assert((public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":0,"currency":"CAD","revision":0}')->>'revision')::bigint=1,'lost-response repeat not another revision');
select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":1234,"currency":"CAD","revision":1}');
select public.b14_reject($q$select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":999,"currency":"CAD","revision":0}')$q$,'40001');
select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":null,"currency":"CAD","revision":2}');
select public.b14_reject($q$select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":-1,"currency":"CAD","revision":3}')$q$,'23514');
select public.b14_reject($q$select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":1.5,"currency":"CAD","revision":3}')$q$,'23514');
select public.b14_reject($q$select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":9007199254740992,"currency":"CAD","revision":3}')$q$,'23514');
select public.b14_reject($q$select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":1,"currency":"USD","revision":3}')$q$,'23514');
select public.b14_reject($q$select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='cost'),'{"amountCents":1,"currency":"CAD","revision":3,"ownerId":"forged"}')$q$,'23514');
select public.b14_reject('select * from marketplace_private.shop_product_costs','42501');
select public.b14_reject('select * from marketplace_private.shop_expenses','42501');
select public.b14_reject('select * from marketplace_private.shop_order_cost_snapshots','42501');
select public.marketplace_shop_expenses('create','{"id":"18100000-0000-4000-8000-000000000001","amountCents":1250,"currency":"CAD","on":"2024-02-29","kind":"Packaging","description":"Local expense"}');
select public.b14_assert((public.marketplace_shop_expenses('create','{"id":"18100000-0000-4000-8000-000000000001","amountCents":1250,"currency":"CAD","on":"2024-02-29","kind":"Packaging","description":"Local expense"}')->>'revision')::bigint=1,'expense create repeat');
select public.marketplace_shop_expenses('update','{"id":"18100000-0000-4000-8000-000000000001","amountCents":1500,"currency":"CAD","on":"2024-02-29","kind":"Other","description":"Edited","revision":1}');
select public.b14_assert((public.marketplace_shop_expenses('update','{"id":"18100000-0000-4000-8000-000000000001","amountCents":1500,"currency":"CAD","on":"2024-02-29","kind":"Other","description":"Edited","revision":1}')->>'revision')::bigint=2,'edit acknowledgement retry');
select public.b14_reject($q$select public.marketplace_shop_expenses('delete','{"id":"18100000-0000-4000-8000-000000000001","revision":1}')$q$,'40001');
select public.marketplace_shop_expenses('delete','{"id":"18100000-0000-4000-8000-000000000001","revision":2}');
select public.marketplace_shop_expenses('delete','{"id":"18100000-0000-4000-8000-000000000001","revision":2}');
select public.b14_assert(public.marketplace_shop_expenses('create','{"id":"18100000-0000-4000-8000-000000000001","amountCents":1250,"currency":"CAD","on":"2024-02-29","kind":"Packaging","description":"Local expense"}')->>'deletedAt' is not null,'initial create retry never resurrects deleted expense');
select public.b14_assert(jsonb_array_length(public.marketplace_shop_expenses('list','{}')->'expenses')=0,'deleted excluded');
select public.b14_reject($q$select public.marketplace_shop_expenses('update','{"id":"18100000-0000-4000-8000-000000000001","amountCents":1500,"currency":"CAD","on":"2024-02-29","kind":"Other","description":"Edited","revision":3}')$q$,'40001');
select public.b14_reject($q$select public.marketplace_shop_expenses('create','{"id":"18100000-0000-4000-8000-000000000001","amountCents":999,"currency":"CAD","on":"2024-02-29","kind":"Other","description":"forged retry"}')$q$,'40001');
select public.b14_reject($q$select public.marketplace_shop_expenses('create','{"id":"18100000-0000-4000-8000-000000000002","amountCents":0,"currency":"CAD","on":"2024-02-29","kind":"Other","description":"bad"}')$q$,'23514');
select public.b14_reject($q$select public.marketplace_shop_expenses('create','{"id":"18100000-0000-4000-8000-000000000002","amountCents":1,"currency":"CAD","on":"2999-01-01","kind":"Other","description":"bad"}')$q$,'23514');
select public.b14_reject($q$select public.marketplace_shop_expenses('create','{"id":"18100000-0000-4000-8000-000000000002","amountCents":1,"currency":"CAD","on":"2023-02-29","kind":"Other","description":"bad"}')$q$,'22008');
select public.b14_reject($q$select public.marketplace_shop_expenses('create','{"id":"18100000-0000-4000-8000-000000000002","amountCents":1,"currency":"CAD","on":"2024-01-01","kind":"Subscription","description":"not a billing event"}')$q$,'23514');
reset role;
select set_config('request.jwt.claim.sub',public.b14_owner(82)::text,false);
set role authenticated;
select public.b14_reject('select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind=''cost''))','42501');
select public.b14_assert(jsonb_array_length(public.marketplace_shop_expenses('list','{}')->'expenses')=0,'other Shop list private');
select public.b14_reject($q$select public.marketplace_shop_expenses('delete','{"id":"18100000-0000-4000-8000-000000000001","revision":3}')$q$,'42501');
reset role;
select set_config('request.jwt.claim.sub',public.b14_owner(85)::text,false);
set role authenticated;
select public.b14_assert((public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='suspended'),'{"amountCents":0,"currency":"CAD","revision":0}')->>'amountCents')::bigint=0,'Suspended private management');
select public.marketplace_shop_expenses('create','{"id":"18500000-0000-4000-8000-000000000001","amountCents":500,"currency":"CAD","on":"2024-01-01","kind":"Other","description":"Suspended retained"}');
reset role;
select set_config('request.jwt.claim.sub','',false);
set role anon;
select public.b14_reject('select public.marketplace_shop_expenses(''list'',''{}'')','42501');
reset role;
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',false);
set role authenticated;
select public.b14_reject('select public.marketplace_shop_expenses(''list'',''{}'')','42501');
reset role;
select set_config('request.jwt.claim.sub',public.b14_owner(81)::text,false);
insert into public.b18_scope(kind,lid) select 'resale',id from public.listings where seller_id=public.b14_owner(81) and listing_channel='resale' limit 1;
-- B17 deletes its Resale fixture; create a new normal Resale draft for denial.
insert into public.listings(id,seller_id,title,description,price_cents,currency,category,subcategory,condition,expected_image_count,preferred_payment_mode,preferred_fulfillment,meeting_location,estimated_delivery_fee_cents)
values('18800000-0000-4000-8000-000000000001',public.b14_owner(81),'Resale','Local',100,'CAD','Electronics','Cameras','good',1,'external','ON_CAMPUS','Campus',0);
select public.b14_reject($q$select public.marketplace_shop_product_cost('18800000-0000-4000-8000-000000000001','{"amountCents":1,"currency":"CAD","revision":0}')$q$,'42501');
insert into public.b18_scope(kind,lid) values('delete',public.b14_draft(81));
select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='delete'),'{"amountCents":100,"currency":"CAD","revision":0}');
delete from public.listings where id=(select lid from public.b18_scope where kind='delete');
select public.b14_assert((public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='delete'))->>'amountCents')::bigint=100,'deleted Listing retains private cost read');
select public.b14_reject($q$select public.marketplace_shop_product_cost((select lid from public.b18_scope where kind='delete'),'{"amountCents":1,"currency":"CAD","revision":1}')$q$,'42501');
select public.b14_assert(not exists(select 1 from public.b18_prior_functions b join pg_proc p using(oid) where b.def<>pg_get_functiondef(p.oid)),'existing authority definitions unchanged');
select public.b14_assert(not exists(select 1 from public.b18_prior_orders b join public.orders o using(id) where b.original<>to_jsonb(o)),'historical Orders unchanged');
select public.b14_assert(not exists(select 1 from marketplace_private.shop_order_cost_snapshots),'no retrospective Order cost capture');
select public.b14_assert((select count(*)=1 from marketplace_private.shop_expenses where id='18100000-0000-4000-8000-000000000001' and deleted_at is not null),'soft deleted record retained');
do $$declare i integer;v jsonb;cursor_id uuid;begin
 for i in 1..23 loop perform public.marketplace_shop_expenses('create',jsonb_build_object('id',gen_random_uuid(),'amountCents',i,'currency','CAD','on','2024-01-01','kind','Other','description','page'));end loop;
 v:=public.marketplace_shop_expenses('list','{}');perform public.b14_assert(jsonb_array_length(v->'expenses')=20 and v->>'nextCursor' is not null,'bounded stable first page');
 cursor_id:=(v->>'nextCursor')::uuid;v:=public.marketplace_shop_expenses('list',jsonb_build_object('beforeId',cursor_id));perform public.b14_assert(jsonb_array_length(v->'expenses')=3 and v->>'nextCursor' is null,'second page no duplicates');
end;$$;
